/// A decoration printed after an operand (XED's operand
/// conversions): text chosen by a decoder field, or the `+n` of an
/// operand naming several registers.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Conversion {
    Zerostr,
    Saestr,
    Roundc,
    Bcaststr,
    Dfvstr,
    /// The operand names this many consecutive registers.
    Multireg(u8),
}
impl Conversion {
    /// The text for decoded fields `s` (XED's `xed_print_cvt`;
    /// `BADCVT` for a value outside the table).
    pub fn text(self, s: &Fields) -> &'static str {
        match self {
            Self::Zerostr => {
                const TEXTS: &[&str] = &["", "{z}"];
                TEXTS
                    .get(usize::from(s.zeroing))
                    .copied()
                    .unwrap_or("BADCVT")
            }
            Self::Saestr => {
                const TEXTS: &[&str] = &["", "{sae}"];
                TEXTS.get(usize::from(s.sae)).copied().unwrap_or("BADCVT")
            }
            Self::Roundc => {
                const TEXTS: &[&str] = &["", "{rne-sae}", "{rd-sae}", "{ru-sae}", "{rz-sae}"];
                TEXTS
                    .get(usize::from(s.roundc))
                    .copied()
                    .unwrap_or("BADCVT")
            }
            Self::Bcaststr => {
                const TEXTS: &[&str] = &[
                    "", "{1to16}", "{4to16}", "{1to8}", "{4to8}", "{1to8}", "{4to8}", "{2to16}",
                    "{2to8}", "{8to16}", "{1to4}", "{1to2}", "{2to4}", "{1to4}", "{1to8}",
                    "{1to16}", "{1to32}", "{1to16}", "{1to32}", "{1to64}", "{2to4}", "{2to8}",
                    "{1to2}", "{1to2}", "{1to4}", "{1to8}", "{1to2}", "{1to4}",
                ];
                TEXTS.get(usize::from(s.bcast)).copied().unwrap_or("BADCVT")
            }
            Self::Dfvstr => {
                const TEXTS: &[&str] = &[
                    "{dfv=}",
                    "{dfv=cf}",
                    "{dfv=zf}",
                    "{dfv=zf,cf}",
                    "{dfv=sf}",
                    "{dfv=sf,cf}",
                    "{dfv=sf,zf}",
                    "{dfv=sf,zf,cf}",
                    "{dfv=of}",
                    "{dfv=of,cf}",
                    "{dfv=of,zf}",
                    "{dfv=of,zf,cf}",
                    "{dfv=of,sf}",
                    "{dfv=of,sf,cf}",
                    "{dfv=of,sf,zf}",
                    "{dfv=of,sf,zf,cf}",
                ];
                TEXTS.get(usize::from(s.dfv)).copied().unwrap_or("BADCVT")
            }
            Self::Multireg(_) => "",
        }
    }
}
